sys_script_client.script:
function onSubmit() {
    var pairs = [
        { score: 'quality_score', reason: 'quality_reason', label: 'Quality' },
        { score: 'delivery_score', reason: 'delivery_reason', label: 'Delivery' },
        { score: 'quantity_score', reason: 'quantity_reason', label: 'Quantity' },
        { score: 'cost_score', reason: 'cost_reason', label: 'Cost' },
        { score: 'documentation_score', reason: 'documentation_reason', label: 'Documentation' },
        { score: 'overall_score', reason: 'overall_reason', label: 'Overall' }
    ];

    var errors = [];

    for (var i = 0; i < pairs.length; i++) {
        var scoreVal = g_form.getValue(pairs[i].score);
        if (scoreVal !== '' && scoreVal !== null && scoreVal !== undefined) {
            var reasonVal = g_form.getValue(pairs[i].reason);
            if (reasonVal === '' || reasonVal === null || reasonVal === undefined || reasonVal.trim() === '') {
                errors.push(pairs[i].label + ' rating reason is required.');
            }
        }
    }

    if (errors.length > 0) {
        for (var j = 0; j < errors.length; j++) {
            g_form.addErrorMessage(errors[j]);
        }
        g_form.addErrorMessage('Please explain why this supplier received the selected score.');
        return false;
    }

    return true;
}
